// pulumi-resource-incident is the provider plugin. It serves Pulumi's gRPC
// provider protocol and translates each call into Terraform CRUD against the
// bridged incident.io provider.
package main

import (
	"context"

	// Allow embedding the generated schema in the plugin binary.
	_ "embed"

	pf "github.com/pulumi/pulumi-terraform-bridge/v3/pkg/pf/tfbridge"

	incident "github.com/incident-io/pulumi-incident/provider"
)

// The schema is embedded so the plugin can answer GetSchema without needing
// the file alongside the binary. Regenerated by `make tfgen`.
//
//go:embed schema.json
var pulumiSchema []byte

func main() {
	pf.Main(context.Background(), "incident", incident.Provider(), pf.ProviderMetadata{
		PackageSchema: pulumiSchema,
	})
}
